    let recorder, recChunks = [], recStream, recTick, recStarted = 0;
    const recStatus = (t) => { $("recStatus").textContent = t; };
    let savedClones = [];
    // The name the session starts with: what you typed if it matches a saved voice, else your newest saved voice.
    // (The server only uses a clone when the name matches, so a blank or mistyped name used to give the stock voice.)
    function sessionName() {
      const typed = $("voiceName").value.trim();
      const match = savedClones.find((c) => c.name.toLowerCase() === typed.toLowerCase());
      if (match) return match.name;
      const newest = [...savedClones].sort((a, b) => String(b.createdAt).localeCompare(String(a.createdAt)))[0];
      if (newest) { $("voiceName").value = newest.name; return newest.name; }
      return typed;
    }
    function voiceNote(name) {
      $("voiceUsed").textContent = savedClones.some((c) => c.name === name)
        ? `Using your cloned voice: ${name}`
        : "No saved voice yet, so Uncle uses a stock voice. Record yourself in step 1 first.";
    }
    async function refreshSaved() {
      try {
        const list = await (await fetch("/api/voice/clones")).json();
        savedClones = list;
        $("saved").innerHTML = list.length ? "<p>Saved voices:</p>" : "";
        for (const c of list) {
          const row = document.createElement("div");
          row.textContent = c.name + " ";
          const del = document.createElement("button");
          del.textContent = "Delete";
          del.onclick = async () => {
            const r = await fetch("/api/voice/clones/" + encodeURIComponent(c.name), { method: "DELETE" });
            recStatus(r.ok ? `Deleted the saved voice for ${c.name}.` : "Could not delete it.");
            refreshSaved();
          };
          row.appendChild(del);
          $("saved").appendChild(row);
        }
      } catch { /* the list is optional */ }
    }
    refreshSaved();
    $("recStart").onclick = async () => {
      if (!$("voiceName").value.trim()) return recStatus("Please type your name first.");
      try {
        recStream = await navigator.mediaDevices.getUserMedia({ audio: true });
      } catch {
        return recStatus("The microphone is blocked. Allow it in the browser and try again.");
      }
